    static int longestOnes(int[] nums, int k) {

        int n = 0;              // Number of zeros in the current window
        int i = 0;              // Left pointer
        int j = 0;              // Right pointer
        int l = nums.length;

        int MaxSize = Integer.MIN_VALUE;

        while (j < l) {

            // Current element is 1, simply expand the window
            if (nums[j] == 1) {
                j++;
            } else {

                // We can still flip this zero
                if (n < k) {
                    n++;
                    j++;
                } else {

                    // Current window is the largest valid window till now
                    MaxSize = Math.max(MaxSize, j - i);

                    // Shrink the window until one zero is removed
                    while (n == k) {
                        if (nums[i] == 0)
                            n--;
                        i++;
                    }

                    // Include the current zero
                    n++;
                    j++;
                }
            }
        }

        // Check the last valid window
        MaxSize = Math.max(MaxSize, j - i);

        return MaxSize;
    }
